"use client";
import {useState} from 'react';
import {PremiumTabs} from './PremiumTabs';
import './TabBatchB.css';

/* ---------- 1. E-commerce product detail ---------- */
const productImages=['Glazed rim','Speckled clay','Stacked set'];
function PlateArt({variant}:{variant:number}){
 if(variant===0){const rings=[[96,'#d9c8ab',3.5],[73,'#e2d4b8',2],[53,'#cdb995',2.5],[35,'#dccdb0',2]];
  return <svg className="tbb-shop-art" viewBox="0 0 200 184" role="presentation" aria-hidden="true"><rect width="200" height="184" fill="#f3ecdd"/>{rings.map(([r,c,w],i)=><circle key={i} cx="100" cy="92" r={r as number} fill="none" stroke={c as string} strokeWidth={w as number}/>)}<circle cx="100" cy="92" r="19" fill="none" stroke="#e6dac2" strokeWidth="2"/><circle cx="100" cy="92" r="96" fill="none" stroke="#b09468" strokeWidth="1" strokeDasharray="0"/></svg>}
 if(variant===1){const dots=Array.from({length:46},(_,i)=>{const t=i*2.39996;const r=8.8*Math.sqrt(i);return [100+r*Math.cos(t),92+r*Math.sin(t)*.92,2.2+(i%3)*.7];});
  return <svg className="tbb-shop-art" viewBox="0 0 200 184" role="presentation" aria-hidden="true"><rect width="200" height="184" fill="#e5d7bd"/>{dots.map((d,i)=><circle key={i} cx={d[0]} cy={d[1]} r={d[2]} fill={i%2?'#c3ad85':'#b39a72'}/>)}</svg>}
 const widths=[172,150,128,106];
 return <svg className="tbb-shop-art" viewBox="0 0 200 184" role="presentation" aria-hidden="true"><rect width="200" height="184" fill="#f3ecdd"/>{widths.map((w,i)=>{const h=26,y=138-i*27;return <g key={i}><ellipse cx="100" cy={y} rx={w/2} ry="13" fill={['#d9c8ab','#e2d5bb','#eadfc8','#f2e9d6'][i]} stroke="#b09468" strokeWidth="1.5"/><ellipse cx="100" cy={y-3} rx={w/2-12} ry="8" fill="none" stroke="#c4b28c" strokeWidth="1"/></g>})}</svg>}
const specs=[['Material','High-fired stoneware, reactive glaze'],['In the box','4 dinner plates, 4 side plates, 4 bowls'],['Diameter','Dinner plate 27 cm · bowl 15 cm'],['Weight','620 g per dinner plate'],['Care','Dishwasher and microwave safe'],['Made in','Khurja, Uttar Pradesh'],['SKU','KH-AMB-12']];
const reviews=[['Meera S.','Bengaluru','The glaze is even better in person. Each plate is slightly different, which is exactly what I wanted.',47,5],['Danish K.','Pune','Solid weight, stacks neatly, and nothing has chipped after two months of daily use.',19,5],['Anaya R.','Kochi','Beautiful set. One bowl arrived with a small crack and support replaced it within a week.',31,4]];
function DetailsPanel(){return <div className="tbb-shop-details"><div><h3>Made to be used every day.</h3><p>Each piece is thrown, glazed and fired in small batches, so no two sets are exactly alike. The amber glaze breaks darker at the rim and stays smooth where food meets the plate.</p><p>The clay is sourced from Uttar Pradesh and fired at 1,220°C, which makes the body dense enough for daily stacking without chipping at the edges.</p></div><div className="tbb-shop-care"><b>Good to know</b><p><span>✓</span> Ships in 2–4 days, packed in moulded pulp</p><p><span>✓</span> 10-day replacement for transit damage</p><p><span>✓</span> Glaze is lead-free and food safe</p></div></div>}
function SpecsPanel(){return <table className="tbb-shop-specs"><tbody>{specs.map(r=><tr key={r[0]}><th scope="row">{r[0]}</th><td>{r[1]}</td></tr>)}</tbody></table>}
function ReviewsPanel(){const[votes,setVotes]=useState([0,0,0]);return <div className="tbb-shop-reviews"><div className="tbb-shop-score"><b>4.7</b><span aria-label="Rated 4.7 out of 5">★★★★★</span><small>128 verified reviews</small><div>{[[5,98],[4,21],[3,6],[2,2],[1,1]].map(([s,n])=><p key={s}><span>{s}★</span><i><em style={{width:`${n/98*100}%`}}/></i>{n}</p>)}</div></div><div className="tbb-shop-review-list">{reviews.map((r,i)=><article key={r[0] as string}><header><span className={`tbb-shop-avatar av-${i}`}>{(r[0] as string)[0]}</span><div><b>{r[0]}</b><small>{r[1]} · {'★'.repeat(r[4] as number)}</small></div></header><p>{r[2]}</p><button aria-pressed={votes[i]===1} onClick={()=>setVotes(v=>v.map((x,k)=>k===i?(x?0:1):x))}>{votes[i]?'✓ Helpful':'Helpful'} ({(r[3] as number)+votes[i]})</button></article>)}</div></div>}
export function ProductDetailScreen(){const[img,setImg]=useState(0),[colour,setColour]=useState(1),[qty,setQty]=useState(1),[added,setAdded]=useState(false);
 return <section className="tbb-screen tbb-shop" aria-label="Product detail tabs screen"><div className="tbb-shop-top"><div className="tbb-shop-gallery"><div className="tbb-shop-photo" role="img" aria-label={`Product photograph: ${productImages[img]}`}><PlateArt key={img} variant={img}/></div><div className="tbb-shop-thumbs">{productImages.map((t,i)=><button key={t} className={i===img?'on':''} aria-label={`Show ${t}`} aria-pressed={i===img} onClick={()=>setImg(i)}><PlateArt variant={i}/></button>)}</div></div><div className="tbb-shop-buy"><span className="tbb-shop-brand">Kilnhouse</span><h2>Amber stoneware dinner set</h2><p className="tbb-shop-rating"><span aria-label="Rated 4.7 out of 5">★★★★★</span> 4.7 · 128 reviews</p><p className="tbb-shop-price">₹4,850 <s>₹6,200</s> <small>incl. all taxes</small></p><div className="tbb-shop-colours"><span>Glaze</span>{['Amber','Smoke','Moss'].map((c,i)=><button key={c} className={i===colour?'on':''} aria-pressed={i===colour} onClick={()=>setColour(i)}><i className={`sw-${i}`}/>{c}</button>)}</div><div className="tbb-shop-row"><div className="tbb-shop-qty"><button aria-label="Decrease quantity" onClick={()=>setQty(q=>Math.max(1,q-1))}>−</button><b aria-live="polite">{qty}</b><button aria-label="Increase quantity" onClick={()=>setQty(q=>Math.min(4,q+1))}>+</button></div><button className="tbb-shop-add" onClick={()=>setAdded(true)}>{added?'✓ Added to bag':'Add to bag · ₹'+(4850*qty).toLocaleString('en-IN')}</button></div><p className="tbb-shop-delivery">Free delivery to <b>Bengaluru 560038</b> by Saturday</p></div></div>
<PremiumTabs label="Product information" variant={0} items={[{id:'details',label:'Details',content:<DetailsPanel/>},{id:'specs',label:'Specifications',content:<SpecsPanel/>},{id:'reviews',label:'Reviews',badge:'128',content:<ReviewsPanel/>}]}/></section>}

/* ---------- 2. Restaurant menu ---------- */
const menu:{meal:string;items:[string,string,string,string?][]}[]=[
 {meal:'Breakfast',items:[['Soft idli, podi & ghee','Four pillow-soft idlis with sesame podi','120','veg'],['Eggs Kejriwal','Sourdough, fried eggs, green chilli and cheese','240'],['Akuri on toast','Parsi-style spiced scrambled eggs','260','spicy'],['Ragi dosa','Finger millet crepe, coconut chutney','180','veg'],['Filter coffee custard','Set custard with a dark coffee top','160','veg'],['Watermelon & mint bowl','With toasted pumpkin seeds','150','vegan']]},
 {meal:'Lunch',items:[['Jackfruit sukka','Coastal style, with neer dosa','320','veg'],['Chicken ghee roast','Byadgi chillies, served with appam','420','spicy'],['Beetroot & feta salad','Curry-leaf vinaigrette, candied walnuts','280','veg'],['Mangalore fish curry','Seer fish, tamarind and coconut milk','460'],['Millet khichdi','Slow-cooked, with smoked curd','240','veg'],['Tender coconut payasam','Served chilled','180','veg']]},
 {meal:'Drinks',items:[['South filter coffee','Strong, frothed, slightly sweet','90','veg'],['Masala chai','Brewed with crushed ginger','80','veg'],['Kokum soda','Sour, salty, very cold','140','vegan'],['Mango lassi','Alphonso, hung curd, cardamom','160','veg'],['Tender coconut cooler','With basil seeds','130','vegan'],['Spiced buttermilk','Curry leaf and green chilli','90','veg']]}];
function MenuPanel({meal}:{meal:number}){const[vegOnly,setVeg]=useState(false);const items=menu[meal].items.filter(i=>!vegOnly||i[3]==='veg'||i[3]==='vegan');
 return <div className="tbb-menu-panel"><div className="tbb-menu-tools"><p>{menu[meal].meal==='Breakfast'?'Served 8:00 – 11:30':menu[meal].meal==='Lunch'?'Served 12:00 – 15:30':'All day'}</p><label><input type="checkbox" checked={vegOnly} onChange={e=>setVeg(e.target.checked)}/> Vegetarian only</label></div><ul key={String(vegOnly)}>{items.map(i=><li key={i[0]}><div><b>{i[0]}{i[3]&&<i className={i[3]}>{i[3]==='vegan'?'vegan':i[3]}</i>}</b><small>{i[1]}</small></div><span>₹{i[2]}</span></li>)}</ul></div>}
export function RestaurantMenuScreen(){return <section className="tbb-screen tbb-menu" aria-label="Restaurant menu tabs screen"><header className="tbb-menu-head"><span className="tbb-menu-mono">F&F</span><h2>Fig & Fennel</h2><p>All-day kitchen · 12th Main, Indiranagar · Open till 23:00</p></header><PremiumTabs label="Menu section" variant={0} items={menu.map((m,i)=>({id:m.meal.toLowerCase(),label:m.meal,content:<MenuPanel meal={i}/>}))}/><footer className="tbb-menu-foot">Menu shown for browsing · no ordering in this preview</footer></section>}

/* ---------- 3. Chat workspace ---------- */
type Thread={who:string;av:number;time:string;text:string;replies:[string,string][];unread?:boolean};
const initialThreads:Thread[]=[
 {who:'Priya Nair',av:0,time:'09:52',text:'Dropped the revised onboarding flow in the shared folder. Can two people walk through the empty states before standup?',replies:[['Ravi Menon','On it, checking the mobile widths now.'],['Komal Shah','Empty state copy reads well. One suggestion on the second screen.']],unread:true},
 {who:'Ravi Menon',av:1,time:'09:14',text:'The export job finished overnight. Numbers look sane, sharing the summary sheet here in a bit.',replies:[['Priya Nair','Nice. Does it include the weekend traffic?']]},
 {who:'Komal Shah',av:2,time:'Yesterday',text:'Reminder: Thursday review moved to 15:30. Bring one thing you would cut from the current scope.',replies:[]}];
const chatFiles=[['▧','Launch checklist.pdf','PDF · 340 KB','Priya · 10:02'],['▤','Empty states v3.fig','Design · 8.1 MB','Komal · 09:40'],['▭','Traffic summary.csv','Sheet · 96 KB','Ravi · Yesterday'],['▧','Vendor agreement.pdf','PDF · 1.1 MB','Priya · Monday']];
const mentions=[['Priya Nair','#design-crit','@jamie can you sanity-check the contrast on the disabled states?','09:58'],['Ravi Menon','#releases','@jamie the 1.4.2 tag is yours to publish when ready.','08:31']];
function ThreadsPanel(){const[threads,setThreads]=useState(initialThreads),[open,setOpen]=useState(-1),[draft,setDraft]=useState('');
 const post=()=>{if(!draft.trim()||open<0)return;setThreads(t=>t.map((x,i)=>i===open?{...x,replies:[...x.replies,['Jamie Lane',draft.trim()] as [string,string]]}:x));setDraft('');};
 return <div className="tbb-chat-threads">{threads.map((t,i)=><div className={`tbb-chat-thread ${open===i?'open':''}`} key={t.who}><button className="tbb-chat-starter" aria-expanded={open===i} onClick={()=>{setOpen(open===i?-1:i);setThreads(ts=>ts.map((x,k)=>k===i?{...x,unread:false}:x));}}><span className={`tbb-chat-av av-${t.av}`}>{t.who.split(' ').map(w=>w[0]).join('')}</span><span className="tbb-chat-copy"><b>{t.who}<time>{t.time}</time></b><span>{t.text}</span><small>{t.replies.length?`${t.replies.length} ${t.replies.length===1?'reply':'replies'}`:'No replies yet'}{t.unread&&<i>new</i>}</small></span></button>{open===i&&<div className="tbb-chat-replies">{t.replies.map((r,k)=><p key={k}><b>{r[0]}</b>{r[1]}</p>)}<div className="tbb-chat-replybox"><input aria-label={`Reply to ${t.who}`} placeholder={`Reply to ${t.who.split(' ')[0]}…`} value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')post();}}/><button onClick={post} disabled={!draft.trim()}>Reply</button></div></div>}</div>)}</div>}
function FilesPanel(){const[got,setGot]=useState<number[]>([]);return <div className="tbb-chat-files">{chatFiles.map((f,i)=><div className="tbb-chat-file" key={f[1]}><span>{f[0]}</span><div><b>{f[1]}</b><small>{f[2]}</small></div><time>{f[3]}</time><button aria-pressed={got.includes(i)} onClick={()=>setGot(g=>g.includes(i)?g.filter(x=>x!==i):[...g,i])}>{got.includes(i)?'✓ Saved':'Save'}</button></div>)}</div>}
function MentionsPanel(){const[read,setRead]=useState<number[]>([]);return <div className="tbb-chat-mentions">{mentions.map((m,i)=><article className={read.includes(i)?'read':''} key={m[3]}><header><b>{m[0]}</b><span>{m[1]}</span><time>{m[3]}</time></header><p>{m[2]}</p><button onClick={()=>setRead(r=>r.includes(i)?r:[...r,i])}>{read.includes(i)?'✓ Read':'Mark read'}</button></article>)}{read.length===mentions.length&&<p className="tbb-chat-clear">All caught up ✓</p>}</div>}
export function ChatWorkspaceScreen(){return <section className="tbb-screen tbb-chat" aria-label="Chat workspace tabs screen"><aside className="tbb-chat-side"><b className="tbb-chat-logo">◔ loopin</b><span className="tbb-chat-side-h">CHANNELS</span><p className="on"># design-crit</p><p># releases</p><p># random</p><span className="tbb-chat-side-h">DIRECT</span><p><i className="dot"/> Priya Nair</p><p><i className="dot away"/> Ravi Menon</p></aside><div className="tbb-chat-main"><header className="tbb-chat-head"><b># design-crit</b><span>4 members</span></header><PremiumTabs label="Conversation views" variant={1} items={[{id:'threads',label:'Threads',content:<ThreadsPanel/>},{id:'files',label:'Files',badge:'4',content:<FilesPanel/>},{id:'mentions',label:'Mentions',badge:'2',content:<MentionsPanel/>}]}/></div></section>}

/* ---------- 4. Fitness dashboard ---------- */
const week=[['Mon',62],['Tue',78],['Wed',45],['Thu',88],['Fri',71],['Sat',96],['Sun',54]];
function Rings(){return <svg className="tbb-fit-rings" viewBox="0 0 120 120" role="img" aria-label="Activity rings: move 78 percent, exercise 65 percent, stand 90 percent">{[['#e8533a',52,78],['#8db63f',40,65],['#3f8fb6',28,90]].map(([c,r,p],i)=>{const C=2*Math.PI*(r as number);return <g key={i}><circle cx="60" cy="60" r={r as number} fill="none" stroke="#eceae4" strokeWidth="9"/><circle className="tbb-ring-anim" style={{['--full' as string]:C,['--off' as string]:C*(1-(p as number)/100),animationDelay:`${i*120}ms`}} cx="60" cy="60" r={r as number} fill="none" stroke={c as string} strokeWidth="9" strokeLinecap="round" strokeDasharray={C} strokeDashoffset={C*(1-(p as number)/100)} transform="rotate(-90 60 60)"/></g>})}</svg>}
function ActivityPanel(){const[day,setDay]=useState(5);return <div className="tbb-fit-activity"><div className="tbb-fit-hero"><Rings/><div className="tbb-fit-ring-legend"><p><i className="a"/>Move <b>{412+day*37} kcal</b></p><p><i className="b"/>Exercise <b>{38+day*3} min</b></p><p><i className="c"/>Stand <b>{10+day%3} hr</b></p></div></div><div className="tbb-fit-week" role="group" aria-label={`Steps by day this week. Selected ${week[day][0]} with ${week[day][1]} percent of goal.`}>{week.map((d,i)=><button key={d[0]} className={i===day?'on':''} aria-pressed={i===day} onClick={()=>setDay(i)}><span><em style={{height:`${d[1]}%`}}/></span><small>{d[0]}</small></button>)}</div><div className="tbb-fit-stats"><p><span>Steps</span><b>{(6430+day*511).toLocaleString('en-IN')}</b></p><p><span>Distance</span><b>{(4.6+day*0.4).toFixed(1)} km</b></p><p><span>Flights</span><b>{6+day}</b></p></div></div>}
function SleepPanel(){return <div className="tbb-fit-sleep"><div className="tbb-fit-sleep-head"><b>7h 24m</b><span>in bed 23:12 – 06:48</span></div><div className="tbb-fit-hypno" role="img" aria-label="Sleep stages through the night: mostly light sleep, deep sleep between midnight and 2 am, REM after 4 am.">{[['rem',20],['light',55],['deep',80],['light',50],['awake',12],['deep',75],['light',58],['rem',25],['light',48],['rem',22]].map((s,i)=><span key={i} className={s[0] as string} style={{height:s[1] as number}}/>)}</div><div className="tbb-fit-sleep-grid"><p><span>Deep</span><b>1h 38m</b></p><p><span>REM</span><b>1h 52m</b></p><p><span>Light</span><b>3h 41m</b></p><p><span>Awake</span><b>13m</b></p></div></div>}
function RecoveryPanel(){return <div className="tbb-fit-recovery"><div className="tbb-fit-gauge"><svg viewBox="0 0 120 72" role="img" aria-label="Readiness score 82 out of 100"><path d="M10 66 A 52 52 0 0 1 110 66" fill="none" stroke="#eceae4" strokeWidth="10" strokeLinecap="round"/><path className="tbb-gauge-arc" d="M10 66 A 52 52 0 0 1 110 66" fill="none" stroke="#3f8fb6" strokeWidth="10" strokeLinecap="round" strokeDasharray="164" strokeDashoffset="30"/>{Array.from({length:11},(_,i)=>{const a=Math.PI-(i/10)*Math.PI;const x1=60+43*Math.cos(a),y1=66-43*Math.sin(a),x2=60+47*Math.cos(a),y2=66-47*Math.sin(a);return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke={i<=8?'#3f8fb6':'#cfd8dc'} strokeWidth="1.4"/>})}<text x="60" y="58" textAnchor="middle">82</text></svg><span>Readiness</span></div><div className="tbb-fit-rec-rows"><p><span>Resting heart rate</span><b>54 bpm</b><i className="good">−2 vs avg</i></p><p><span>HRV</span><b>68 ms</b><i className="good">+6 vs avg</i></p><p><span>Body battery</span><b>91</b><i>charged overnight</i></p></div><p className="tbb-fit-tip">Good day for intervals. Recovery is above your 14-day baseline.</p></div>}
export function FitnessDashboardScreen(){return <section className="tbb-screen tbb-fit" aria-label="Fitness dashboard tabs screen"><header className="tbb-fit-head"><div><h2>Good morning, Aarav</h2><p>Saturday, 22 November</p></div><span className="tbb-fit-streak">12-day streak</span></header><PremiumTabs label="Health metrics" variant={0} orientation="vertical" items={[{id:'activity',label:'Activity',content:<ActivityPanel/>},{id:'sleep',label:'Sleep',content:<SleepPanel/>},{id:'recovery',label:'Recovery',content:<RecoveryPanel/>}]}/></section>}

/* ---------- 5. Help center ---------- */
const steps=[['Create your workspace','Pick a name your team will recognize. You can rename it later.'],['Invite your team','Send invites by email, up to 10 seats on the starter plan.'],['Connect your tools','Calendar and file storage link in one click from Settings.'],['Set up your first project','Use the blank template or import from a spreadsheet.']];
const articles=[['Changing your plan mid-cycle','Account'],['Resetting a lost password','Account'],['Importing data from another tool','Getting started'],['Understanding roles and permissions','Getting started'],['Fixing sync that seems stuck','Troubleshooting'],['Why exports can take a few minutes','Troubleshooting']];
function StartPanel(){const[done,setDone]=useState([true,true,false,false]);const n=done.filter(Boolean).length;
 return <div className="tbb-help-steps"><div className="tbb-help-progress"><span style={{width:`${n/4*100}%`}}/><b>{n} of 4 complete</b></div>{steps.map((s,i)=><label className={`tbb-help-step ${done[i]?'done':''}`} key={s[0]}><input type="checkbox" checked={done[i]} onChange={e=>setDone(d=>d.map((x,k)=>k===i?e.target.checked:x))}/><span className="tbb-help-box" aria-hidden="true">{done[i]?'✓':i+1}</span><span><b>{s[0]}</b><small>{s[1]}</small></span></label>)}</div>}
function AccountPanel(){const[on,setOn]=useState([true,false,true]);return <div className="tbb-help-settings">{[['Two-factor authentication','Strongly recommended for workspace owners.'],['Public profile','Show your name and role to people outside the workspace.'],['Billing emails','Invoices and receipts, sent monthly.']].map((s,i)=><div className="tbb-help-setting" key={s[0]}><span><b>{s[0]}</b><small>{s[1]}</small></span><button role="switch" aria-checked={on[i]} onClick={()=>setOn(v=>v.map((x,k)=>k===i?!x:x))}><i/></button></div>)}</div>}
const faqs=[['The app says I am offline, but I am not','This usually means a stuck background sync. Pull to refresh, then check Settings → Sync. If it persists, sign out and back in. Your data is safe on the server.'],['Can I undo a deleted project?','Yes. Deleted projects sit in Trash for 30 days. Owners can restore them from Settings → Trash.'],['Why does my export look different on mobile?','Exports use the desktop layout by default. Choose “Compact” in the export dialog for a mobile-friendly file.']];
function TroublePanel(){const[open,setOpen]=useState(0);return <div className="tbb-help-faq"><div className="tbb-help-status"><i/>All systems operational <span>Updated 4 min ago</span></div>{faqs.map((f,i)=><div className={`tbb-help-q ${open===i?'open':''}`} key={f[0]}><button aria-expanded={open===i} onClick={()=>setOpen(open===i?-1:i)}>{f[0]}<span>{open===i?'−':'+'}</span></button>{open===i&&<p>{f[1]}</p>}</div>)}</div>}
export function HelpCenterScreen(){const[q,setQ]=useState('');const hits=q.trim()?articles.filter(a=>(a[0]+a[1]).toLowerCase().includes(q.trim().toLowerCase())):articles;
 return <section className="tbb-screen tbb-help" aria-label="Help center tabs screen"><header className="tbb-help-hero"><h2>How can we help?</h2><div className="tbb-help-search"><span>⌕</span><input aria-label="Search help articles" placeholder="Search articles, guides and fixes…" value={q} onChange={e=>setQ(e.target.value)}/></div>{q.trim()&&<div className="tbb-help-hits">{hits.length?hits.map(a=><p key={a[0]}><span>{a[1]}</span>{a[0]}</p>):<p className="none">No articles match “{q.trim()}”.</p>}</div>}</header>
<PremiumTabs label="Help topics" variant={0} items={[{id:'start',label:'Getting started',content:<StartPanel/>},{id:'account',label:'Account',content:<AccountPanel/>},{id:'trouble',label:'Troubleshooting',content:<TroublePanel/>}]}/></section>}

/* ---------- 6. CRM contact ---------- */
const timeline=[['✉','Proposal email sent','Shared the revised quote for the winter fabric line.','Today, 10:12'],['☎','Call logged','Spoke 14 min. She wants two delivery slots instead of one.','Yesterday'],['⇄','Deal moved to Negotiation','Trident Fabrics · Winter line · ₹4.2L','Tuesday'],['◷','Meeting held','Met at their Whitefield office with her sourcing team.','Last week']];
function OverviewPanel(){const[tasks,setTasks]=useState([false,true,false]);return <div className="tbb-crm-overview"><div className="tbb-crm-grid"><div className="tbb-crm-card"><h3>Contact details</h3>{[['Email','riya@tridentfabrics.in'],['Phone','+91 98450 12231'],['Owner','Jamie Lane'],['Source','Referral · March 2026']].map(r=><p key={r[0]}><span>{r[0]}</span><b>{r[1]}</b></p>)}</div><div className="tbb-crm-card"><h3>Open deals</h3>{[['Winter fabric line','₹4.2L','Negotiation',72],['Linen restock','₹2.2L','Proposal sent',45]].map(d=><div className="tbb-crm-deal" key={d[0] as string}><p><b>{d[0]}</b><span>{d[1]}</span></p><div className="tbb-crm-stage"><i style={{width:`${d[3]}%`}}/><small>{d[2]}</small></div></div>)}</div></div><div className="tbb-crm-tasks"><h3>Next steps</h3>{[['Send two-slot delivery plan','Due today'],['Chase sign-off on the quote','Due Monday'],['Book December review meeting','Due 28 Nov']].map((t,i)=><label key={t[0]} className={tasks[i]?'done':''}><input type="checkbox" checked={tasks[i]} onChange={e=>setTasks(v=>v.map((x,k)=>k===i?e.target.checked:x))}/><span>{t[0]}</span><small>{t[1]}</small></label>)}</div></div>}
type Note=[string,string,boolean?];
