type Thread={who:string;av:number;time:string;text:string;replies:[string,string][];unread?:boolean};
const initialThreads:Thread[]=[
 {who:'Priya Nair',av:0,time:'09:52',text:'Dropped the revised onboarding flow in the shared folder. Can two people walk through the empty states before standup?',replies:[['Ravi Menon','On it, checking the mobile widths now.'],['Komal Shah','Empty state copy reads well. One suggestion on the second screen.']],unread:true},
 {who:'Ravi Menon',av:1,time:'09:14',text:'The export job finished overnight. Numbers look sane, sharing the summary sheet here in a bit.',replies:[['Priya Nair','Nice. Does it include the weekend traffic?']]},
 {who:'Komal Shah',av:2,time:'Yesterday',text:'Reminder: Thursday review moved to 15:30. Bring one thing you would cut from the current scope.',replies:[]}];
