function ThreadsPanel(){const[threads,setThreads]=useState(initialThreads),[open,setOpen]=useState(-1),[draft,setDraft]=useState('');
 const post=()=>{if(!draft.trim()||open<0)return;setThreads(t=>t.map((x,i)=>i===open?{...x,replies:[...x.replies,['Jamie Lane',draft.trim()] as [string,string]]}:x));setDraft('');};
 return <div className="tbb-chat-threads">{threads.map((t,i)=><div className={`tbb-chat-thread ${open===i?'open':''}`} key={t.who}><button className="tbb-chat-starter" aria-expanded={open===i} onClick={()=>{setOpen(open===i?-1:i);setThreads(ts=>ts.map((x,k)=>k===i?{...x,unread:false}:x));}}><span className={`tbb-chat-av av-${t.av}`}>{t.who.split(' ').map(w=>w[0]).join('')}</span><span className="tbb-chat-copy"><b>{t.who}<time>{t.time}</time></b><span>{t.text}</span><small>{t.replies.length?`${t.replies.length} ${t.replies.length===1?'reply':'replies'}`:'No replies yet'}{t.unread&&<i>new</i>}</small></span></button>{open===i&&<div className="tbb-chat-replies">{t.replies.map((r,k)=><p key={k}><b>{r[0]}</b>{r[1]}</p>)}<div className="tbb-chat-replybox"><input aria-label={`Reply to ${t.who}`} placeholder={`Reply to ${t.who.split(' ')[0]}…`} value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')post();}}/><button onClick={post} disabled={!draft.trim()}>Reply</button></div></div>}</div>)}</div>}
function FilesPanel(){const[got,setGot]=useState<number[]>([]);return <div className="tbb-chat-files">{chatFiles.map((f,i)=><div className="tbb-chat-file" key={f[1]}><span>{f[0]}</span><div><b>{f[1]}</b><small>{f[2]}</small></div><time>{f[3]}</time><button aria-pressed={got.includes(i)} onClick={()=>setGot(g=>g.includes(i)?g.filter(x=>x!==i):[...g,i])}>{got.includes(i)?'✓ Saved':'Save'}</button></div>)}</div>}
