function RecoveryPanel(){return <div className="tbb-fit-recovery"><div className="tbb-fit-gauge"><svg viewBox="0 0 120 72" role="img" aria-label="Readiness score 82 out of 100"><path d="M10 66 A 52 52 0 0 1 110 66" fill="none" stroke="#eceae4" strokeWidth="10" strokeLinecap="round"/><path className="tbb-gauge-arc" d="M10 66 A 52 52 0 0 1 110 66" fill="none" stroke="#3f8fb6" strokeWidth="10" strokeLinecap="round" strokeDasharray="164" strokeDashoffset="30"/>{Array.from({length:11},(_,i)=>{const a=Math.PI-(i/10)*Math.PI;const x1=60+43*Math.cos(a),y1=66-43*Math.sin(a),x2=60+47*Math.cos(a),y2=66-47*Math.sin(a);return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke={i<=8?'#3f8fb6':'#cfd8dc'} strokeWidth="1.4"/>})}<text x="60" y="58" textAnchor="middle">82</text></svg><span>Readiness</span></div><div className="tbb-fit-rec-rows"><p><span>Resting heart rate</span><b>54 bpm</b><i className="good">−2 vs avg</i></p><p><span>HRV</span><b>68 ms</b><i className="good">+6 vs avg</i></p><p><span>Body battery</span><b>91</b><i>charged overnight</i></p></div><p className="tbb-fit-tip">Good day for intervals. Recovery is above your 14-day baseline.</p></div>}
